csui.define('csui/controls/table/rows/description/description.view',['csui/lib/underscore', 'csui/lib/jquery', 'csui/lib/marionette', 'csui/utils/base',
'i18n!csui/controls/table/rows/description/impl/nls/lang',
  'hbs!csui/controls/table/rows/description/impl/description',
  'css!csui/controls/table/rows/description/impl/description'
], function (_, $, Marionette, base, lang, template) {

  var DescriptionView = Marionette.ItemView.extend({

    className: function () {
      if (this._collapsedHeightIsOneLine) {
        return "cs-description csui-description-short-lines-1";
      } else {
        return `cs-description${this.model.collection?.node?.get('type') === 136 && this.options?.tableView?.$el.outerWidth()>850?' cs-description-padding-42':''}`;
      } 
    },

    template: template,

    templateHelpers: function () {
      var description = this.model.get("instructions")
        || this.model.get("description") || '',
        summary = this.model.get('summary') || '';
      this.exceededDescription = false;
      //TODO: : Check for alternative solution for  use case when discription length is axactly 255 characters, 
      //we would still show the 3dots(...) in this use case.
      if (this.options.tableView.options.parentView &&
        this.options.tableView.options.parentView.options.useAppContainer &&
        description && description.toString().length > 254) {
        description = description + "...";
        this.exceededDescription = true;
      }
      return {
        complete_description: this.exceededDescription ? lang.suggestedTooltip : description,
        current_description: description,
        complete_summary: summary,
        current_summary: summary,
        descriptionAvailable: description
      };
    },

    ui: {
      description: '.description',
      summary:'.summary',
    },

    constructor: function DescriptionView(options) {

      Marionette.ItemView.prototype.constructor.apply(this, arguments);
    },

  });

  return DescriptionView;

});


csui.define('csui/controls/table/rows/description/search.description.view',['csui/lib/underscore', 'csui/lib/jquery', 'csui/lib/marionette', 'csui/utils/base',
  'csui/controls/table/rows/description/description.view'
], function (_, $, Marionette, base, DescriptionView) {

  var SearchDescriptionView = DescriptionView.extend({

    templateHelpers: function () {
      var description = this.model.get("description"),
          summary = this.model.get("summary"),
          selectedSettings = this.options && this.options.tableView && this.options.tableView.selectedSettings,
          tableRowSummaryAvailable = (this.options && this.options.tableView && this.options.tableView.options.descriptionRowViewOptions.tableRowSummaryAvailable) || false,
          summary_description = false;

      switch (selectedSettings) {
        case 'SD' : {
          summary_description = true;
          break;
        }
        case 'SO' : {
          summary_description = true;
          description = undefined;
          break;
        }
        case 'SP' : {
          summary_description = true;
          summary && (description = undefined);
          break;
        }
        case 'DP' : {
          summary_description = true;
          description && (summary = undefined);
          break;
        }
        case 'DO' : {
          summary = undefined;
          break;
        }
        case 'NONE':
        default : {
          description = summary = undefined;
        }
      }
      return _.extend(DescriptionView.prototype.templateHelpers.apply(this), {
        complete_description: description,
        current_description: description,
        complete_summary: this.model.get("stringifiedSummary") ? this.model.get("stringifiedSummary") : summary,
        current_summary: summary,
        search_description: true,
        search_summary: true,
        summary_description_available: (summary_description && summary) && !tableRowSummaryAvailable,
        descriptionAvailable : description,
        summary_Available: tableRowSummaryAvailable && (summary_description && summary)
      });
    }
  });

  return SearchDescriptionView;
});


csui.define('csui/controls/fileupload/impl/addversion.controller',[
  'csui/lib/underscore',
  'csui/lib/jquery',
  'i18n!csui/controls/fileupload/impl/nls/lang',
  'csui/controls/fileupload/impl/upload.controller',
  'csui/models/fileupload',
  'csui/controls/globalmessage/globalmessage',
  'csui/models/fileuploads',
  'csui/utils/base',
  'csui/utils/url',
  'csui/utils/types/date',
  'csui/utils/types/member',
  'csui/lib/moment',
  "csui/models/version",
  'csui/utils/commandhelper',
  'csui/utils/contexts/factories/usernodepermission',
  'csui/utils/contexts/factories/connector',
  'csui/models/node/node.model',
  'csui/models/node.actions',
], function (_,
    $,
    lang,
    UploadController,
    FileUploadModel,
    GlobalMessage,
    UploadFileCollection,
    base,
    Url,
    date,
    member,
    moment,
    VersionModel,
    CommandHelper,
    UserNodePermissionFactory,
    ConnectorFactory,
    NodeModel,
    NodeActionCollection) {
  'use strict';

  function AddVersionController(options) {
    this.view = options.view;
    this.selectedNode = options.selectedNode;
    this.status = options.status || {};
    this.context = this.status.context || this.view.context;
    this.status.connector = this.context.getObject(ConnectorFactory);

    this.uploadController = new UploadController({
      container : this.view.container,
      context: this.context,
      originatingView : this.view
    });
  }

  _.extend(AddVersionController.prototype, {

    uploadFile: function (file, config) {

      //By this time file is already picked from file dialog window or 'drag and droped' on a document to add version
      var deferred = $.Deferred();
      this.status.actionType = config.actionType;
      this.status.hideWarningAlert = config.hideWarningAlert;
      this.currentLoggedInUserId = this.context.getModel('user').id;
      this.currentModel = this.selectedNode;

      this._ensureNodeAdvanceInfo().then(_.bind(function () {
          this._getLatestVersionAndUploadFile(file, this.status).done(deferred.resolve).fail(
              deferred.reject);

      }, this));

      return deferred.promise();
    },

    _doUpload: function (file) {

      var deferred = $.Deferred();
      this._blockActions();
      var node      = this.selectedNode,
          fileModel = new FileUploadModel({
            file: file
          }, {
            node: node
          });

      file.add_major_version && fileModel.set('add_major_version', true);
      file.description && fileModel.set('description', file.description);
      var uploadFiles = new UploadFileCollection([fileModel]);
      var largeFileSettings = this.view && this.view.largeFileSettingsModel && this.view.largeFileSettingsModel.get('largeFileSettings');
      var minFileSize = largeFileSettings && largeFileSettings.min_size;
      var size = file.size || fileModel.get('file').size;
      var self = this;
      if (size > minFileSize) {

        var largeFile = {
          size: size,
          uploadKey: "",
          state: "pending",
          retryCount: 0,
          fileChunks: {
            slicedFiles: [],
            total: 0
          }
        };
        fileModel.set('largeFile', largeFile);
      }
      this.uploadController.scheduleFileForUpload(fileModel);
      GlobalMessage.showProgressPanel(uploadFiles, {actionType: this.status.actionType});
      fileModel.promise().then(function (fileUploadModel) {
        //After uploading the model if the version is not displayed this if block is unnecessary
        if (node.versions?.commands) {
            fileUploadModel.version.commands = node.versions.commands;
            return fileUploadModel.version
            .fetch()
            .then(function () {
                return fileUploadModel.version;
              });
          }
      })
          .then(function (version) {
            if (version && (node.versions || (!!node.attributes && !!node.attributes.versions))) {
              var sizeinbytes = version.get('file_size'),
                  sizeinkb    = base.formatFileSize(sizeinbytes);
              version.set('file_size_formatted', sizeinkb);
              version.isLocallyCreated = true;
              !!node.versions && node.versions.add(version, {at: 0});
              if (Array.isArray(node.get('versions'))) {
                !!node.attributes && !!node.attributes.versions &&
                node.attributes.versions.push(version.attributes);
              }

            }
          })
          .then(function () {
            // Adding a new version may change the icon, size and last
            // modification time of the parent document
            return true;
          })
          .then(function () {
            // Prevent the node returned in the promise result
            return true;
          })
          .done(function () {
            GlobalMessage.hideFileUploadProgress();
            self.view && self.view.trigger('new:version:added');
            GlobalMessage.showMessage('success', lang.MessageVersionAdded);
            deferred.resolve();
          }).fail(function (error) {
        deferred.reject(error);
      }).always(_.bind(this._unblockActions, this));

      return deferred.promise();

    },

    _checkAdvancedVersionAndUpload: function (file, status, latestVersion) {
      var self     = this,
          node     = this.currentModel,
          deferred = $.Deferred();
          self._getNodePermission().done(function (result){
            var permissionsForNode= result.results.data.permissions.permissions;
            node.set('add_major_version_permission', permissionsForNode.indexOf("add_major_version") > -1, { silent: true });
              self._promoteToSelectVersion(file, status, latestVersion).done(function () {
                self._doUpload(file).done(deferred.resolve).fail(deferred.reject);
              });
           
          }).fail(function (resp) {
            deferred.reject(resp);
          });
      return deferred.promise();
    },

    _promoteToSelectVersion: function (file, status, latestVersion) {
      var self     = this,
          node     = this.currentModel,
          deferred = $.Deferred();
      csui.require([
        'csui/controls/version.control.dialog/version.control.dialog.view',
        'csui/controls/version.control.dialog/add.version.control.view',
        'csui/models/nodes',
        'csui/utils/commands/unreserve'
      ], function (VersionControlDialogView, VersionUpdateView, NodeCollection, UnreserveCommand) {
        _selectVersioning().done(function (result) {
          if (result.promoteToMajor) {
            file.add_major_version = true;
          }
          if(result.description){
            file.description = result.description;
          }
          if (result.reserved) {
            let commandStatus = { nodes: new NodeCollection([node]), context: self.context };
            let unreserveCommand = new UnreserveCommand();
            let promiseFromCommand = unreserveCommand.execute(commandStatus);
            CommandHelper.handleExecutionResults(
              promiseFromCommand, {
              command: unreserveCommand,
              suppressSuccessMessage: commandStatus.suppressSuccessMessage,
              suppressFailMessage: commandStatus.suppressFailMessage
            });
          }
          deferred.resolve();
        }).fail(function () {
          deferred.reject();
        });

        function _selectVersioning() {
          //show popup for select versioning
          const hideWarningMessage = self.currentLoggedInUserId === latestVersion.get('owner_id') ||
                                     self.status.hideWarningAlert || node.get('advanced_versioning');
          const options               = {
                "latestVersion": latestVersion,
                "fileName": file.name,
                "reserved": node.get('reserved'),
                "selectVersion": node.get('advanced_versioning') && node.get('add_major_version_permission'),
                "warningMessage": !hideWarningMessage ? self._getBodyMessage(latestVersion) : undefined, 
                "hideWarningMessage": hideWarningMessage
              },
              view                  = new VersionUpdateView(options),
              versionControloptions = {
                _view: view,
                standardHeader: false,
                title: lang.warnTitle,
                dialogClassName: 'csui-add-version-control',
                actionBtnLabel: lang.AddButtonLabel,
                cancelBtnLabel: lang.cancelButtonLabel
              };
          return new VersionControlDialogView(versionControloptions).show();
        }
      }, self);
      return deferred.promise();
    },

    _ensureNodeAdvanceInfo: function () {
      //TODO: we can get rid of this call, once adavance info is available in node info
      var deferred            = $.Deferred(),
          node                = this.currentModel,
          advanced_versioning = node.get('advanced_versioning');
      if (advanced_versioning === undefined) {
        var tempNode = new NodeModel({id:node.get('id')}, {connector: node.connector});
        //fetch advanced info
        tempNode.fetch({silent: true}).done(function () {
          node.set('advanced_versioning',tempNode.get('advanced_versioning'),{silent:true});
          deferred.resolve();
        }).fail(function () {
          deferred.reject();
        });
      } else {
        deferred.resolve();
      }
      return deferred.promise();
    },

    _getBodyMessage: function (version) {
      var currentDate   = moment(),
          versDate      = date.deserializeDate(version.get('create_date')),
          difference    = currentDate.diff(versDate, 'days'),
          version_owner = member.formatMemberName(
              version.get('owner_id_expand') || version.get('owner_id'));

      if (difference < 2) {
        versDate = date.formatDateTime(versDate);
        return _.str.sformat(lang.warnMessageRecent, version_owner, versDate);
      }
      versDate = date.formatExactDate(versDate);
      return _.str.sformat(lang.warnMessage, version_owner, versDate);
    },

    _getLatestVersionAndUploadFile: function (file, status) {
      var self     = this,
          deferred = $.Deferred();
      self._getLatestVersion(status).done(function (latestVersion) {
            self._checkAdvancedVersionAndUpload(file, self.status, latestVersion).done(
                deferred.resolve).fail(
                deferred.reject);
      });
      return deferred.promise();
    },

    _getLatestVersion: function (status) {
      var deferred     = $.Deferred(),
          connector    = status.connector,
          node         = this.currentModel,
          versionModel = new VersionModel({
            id: node.get("id"),
            version_number: 0,
            expand: encodeURIComponent('versions{owner_id}')
          }, {connector: connector});
      versionModel.fetch().then(_.bind(function (resp, status, jqXHR) {
        deferred.resolve(new VersionModel(resp, {parse: true}));
      }, function (resp) {
        deferred.reject(resp);
      }));
      return deferred.promise();
    },

    _getNodePermission: function () {
      var nodePermission = this.context.getObject(UserNodePermissionFactory, {
        node:this.currentModel
      });
      return nodePermission.fetch();
    },

    _blockActions: function () {
      this.view && this.view.blockActions && this.view.blockActions();
    },

    _unblockActions: function () {
      this.view && this.view.unblockActions && this.view.unblockActions();
    }

  });

  return AddVersionController;

});


