      this.ui.nameEdit.addClass('binf-hidden');
      const {originatingView} = this.options;
      if(originatingView?.el.querySelector('.csui-item-title-menu')?.classList.contains('binf-hidden')){
        originatingView.el.querySelector('.csui-item-title-menu').classList.remove('binf-hidden');
      }
      this._checkAndEnableOrDisableEditing();

