csui.define('csui/controls/table/impl/column.menu/toolbaritems',[
  'csui/lib/underscore',
  'i18n!csui/controls/table/impl/nls/lang',
  'csui/controls/toolbar/toolitems.factory',
  'csui/themes/csui.jato.action.icons',
  'i18n',
  'csui/themes/carbonfiber/action_icons' // for csui_action_more16
], function (_, lang,
  ToolItemsFactory,
  jatoIcons) {
  'use strict';

  // Keep the keys in sync with csui/widgets/nodestable/toolbaritems.masks
  var toolbarItems = {
    tableColumnToolbar: new ToolItemsFactory({
      sort: [
        {
          signature: "TableColumnSortAscending",
          name: lang.TableColumnMenuSortAscending,
        },
        {
          signature: "TableColumnSortDescending",
          name: lang.TableColumnMenuSortDescending,
        }
      ],
      resize: [
        {
          signature: "TableColumnResizeMinWidth",
          name: lang.TableColumnMenuResizeMinWidth
        },
        {
          signature: "TableColumnResizeFitToContent",
          name: lang.TableColumnMenuFitToContent
        }
      ]
    },
    {
      maxItemsShown: 0, // force toolbar to immediately start with a drop-down list
      dropDownIconSVG: jatoIcons.actionChevronSmallDown,
      dropDownIconName: "csui_action_more16"
    })
  };

  toolbarItems.clone = function () {
    return ToolItemsFactory.cloneToolbarItems(this);
  };

  return toolbarItems;
});


csui.define('csui/controls/table/impl/column.menu/toolbaritems.masks',['module', 'csui/lib/underscore',
  'csui/controls/toolbar/toolitems.mask',
  'csui/utils/toolitem.masks/global.toolitems.mask'
], function (module, _, ToolItemMask, GlobalMenuItemsMask) {
  'use strict';

  // Keep the keys in sync with csui/controls/table/impl/column.menu/toolbaritems
  var toolbars = ['tableColumnToolbar'];

  function ToolbarItemsMasks() {
    var config = module.config(),
        globalMask = new GlobalMenuItemsMask();
    // Create and populate masks for every toolbar
    this.toolbars = _.reduce(toolbars, function (toolbars, toolbar) {
      var mask = new ToolItemMask(globalMask, {normalize: false});
      // Masks passed in by separate require.config calls are sub-objects
      // stored in the outer object be different keys
      _.each(config, function (source, key) {
        source = source[toolbar];
        if (source) {
          mask.extendMask(source);
        }
      });
      // Enable restoring the mask to its initial state
      mask.storeMask();
      toolbars[toolbar] = mask;
      return toolbars;
    }, {});
  }

  ToolbarItemsMasks.toolbars = toolbars;

  return ToolbarItemsMasks;

});


csui.define('csui/controls/table/impl/column.menu/commands',[
  'csui/models/command',
  'csui/models/commands'
], function (
  CommandModel,
  CommandCollection) {

  // As we define only internal table commands here, we use table internal data.

  var TableColumnSortAscendingCommand = CommandModel.extend({
    defaults: {
      signature: "TableColumnSortAscending"
    },

    enabled: function (status, options) {
      // set stateIsOn in the toolItem to let it be drawn in the appropriate state
      const table = status.originatingView.table || status.table;
      const order = table.order()[0];
      status.toolItem.set('stateIsOn', order ? order[0] === status.data.orderIndex && order[1] === 'asc' : false);
      const displayedColumns = status.originatingView.displayedColumns;
      const orderColumn = displayedColumns[status.data.orderIndex];
      return orderColumn.orderable;
    },

    execute: function (status, options) {
      if (!status.toolItem.get('stateIsOn')) {
        status.originatingView.table.column(status.data.orderIndex).order('asc').draw();
      }
    }
  });

  var TableColumnSortDescendingCommand = CommandModel.extend({
    defaults: {
      signature: "TableColumnSortDescending"
    },

    enabled: function (status, options) {
      // set stateIsOn in the toolItem to let it be drawn in the appropriate state
      const table = status.originatingView.table || status.table;
      const order = table.order()[0];
      status.toolItem.set('stateIsOn', order ? order[0] === status.data.orderIndex && order[1] === 'desc' : false);
      const displayedColumns = status.originatingView.displayedColumns;
      const orderColumn = displayedColumns[status.data.orderIndex];
      return orderColumn.orderable;
    },

    execute: function (status, options) {
      if (!status.toolItem.get('stateIsOn')) {
        status.originatingView.table.column(status.data.orderIndex).order('desc').draw();
      }
    }
  });

  var TableColumnResizeMinWidthCommand = CommandModel.extend({
    defaults: {
      signature: "TableColumnResizeMinWidth"
    },

    enabled: function (status, options) {
      return status.originatingView.displayedColumns[status.data.columnIndex].hasResizeHandle;
    },

    execute: function (status, options) {
      const displayedColumns = status.originatingView.displayedColumns;
      const resizeColumn = displayedColumns[status.data.resizeIndex];
      status.originatingView._setColumnToWidth(status.data.resizeIndex, resizeColumn.columnMinWidth);
    }
  });

  var TableColumnResizeFitToContentCommand = CommandModel.extend({
    defaults: {
      signature: "TableColumnResizeFitToContent"
    },

    enabled: function (status, options) {
      return status.originatingView.displayedColumns[status.data.columnIndex].hasResizeHandle;
    },

    execute: function (status, options) {
      status.originatingView._fitColumnToContent(status.data.resizeIndex);
    }
  });

  var commands = new CommandCollection([
    new TableColumnSortAscendingCommand(),
    new TableColumnSortDescendingCommand(),
    new TableColumnResizeMinWidthCommand(),
    new TableColumnResizeFitToContentCommand()
  ]);

  return commands;
});


