csui.define('csui/controls/version.control.dialog/behaviors/version.control.dialog.keyboard.navigation.behavior',[
  'csui/lib/underscore', 'csui/lib/jquery', 'csui/lib/marionette'
], function (_, $, Marionette) {
  'use strict';

// This behavior implements a default keyboard navigation for the version control dialogs.
// Note: for completeness, also do the following in your View code
//  - set focus on the first focusable element after your modal is shown after animation
//    or call setFocusInView function from the view once it is shown.

var VersionControlDialogKeyboardNavigationBehavior = Marionette.Behavior.extend({

  events: {
    'keydown': 'onKeyInView'
  },

  initialize: function () {
    this.view.keyboardBehavior = this;
  },

  _rebuildFocusableElements: function () {
    this.focusables = this.view.$el.find('input[type="radio"]:checked, textarea, otc-checkbox').filter(function (index, elem) {
      return $(elem).is(':visible');
    });
  },

  refreshFocusEngage: function () {
    this._rebuildFocusableElements();
  },

  getCurrentlyFocusedElement: function (shiftTab) {
    if(shiftTab.shiftKey) {
      return $(this.focusables[this.focusables.length - 1]);
    } else {
      return $(this.focusables[0]);
    }
  },

  setFocusInView: function () {
    $(this.focusables[0]).trigger('focus');
  },

  _makeRadiosChecked: function () {
    if(this.radioChanged) {
      this.radioChanged = false;
      this.view.$el.find('*[type="radio"]').filter(function (index, elem) {
        return elem.checked === true;
      }).attr('checked', true);
    }
  },

  isOnLastTabElement: function (shiftTab, event) {
    this._makeRadiosChecked();
    this._rebuildFocusableElements();
    return shiftTab ? event.target === this.focusables[0] : event.target === this.focusables[this.focusables.length - 1];
  },

  onKeyInView: function (event) {
    var keyCode    = event.keyCode;
    switch (keyCode) {
      // left
      // up
      // right
      // down
      case 37:
      case 38:
      case 39:
      case 40:
        if($(event.target).is(':radio')) {
          $(event.target).attr('checked', false);
          this.radioChanged = true;
        }
        break;
    }
  }
});

return VersionControlDialogKeyboardNavigationBehavior;

});


csui.define('csui/controls/version.control.dialog/disable.version.settings.view',['csui/lib/underscore', 'csui/lib/jquery', 'csui/lib/marionette',
  'i18n!csui/controls/version.control.dialog/nls/lang',
  'hbs!csui/controls/version.control.dialog/impl/disable.version.settings',
  'csui/behaviors/keyboard.navigation/tabable.region.behavior',
  'csui/controls/version.control.dialog/behaviors/version.control.dialog.keyboard.navigation.behavior'
], function (_, $, Marionette, lang, template, TabableRegion, VersionControlDialogKeyboardNavigationBehavior) {
  'use strict';

  var DisableVersioningView = Marionette.ItemView.extend({
    constructor: function DisableVersioningView(options) {
      Marionette.ItemView.prototype.constructor.apply(this, arguments);
    },
    className: 'csui-version-control-dialog-view',
    template: template,

    behaviors: {
      TabableRegion: {
        behaviorClass: TabableRegion
      },
      VersionControlDialogKeyboardNavigationBehavior: {
        behaviorClass: VersionControlDialogKeyboardNavigationBehavior
      }
    },

    templateHelpers: function () {
      return {
        disableVersioningTitle: lang.disableVersioningTitle,
        currentFolder: lang.currentFolder,
        currentAndSubfolder: lang.currentAndSubfolder
      };
    },

    onAfterShow: function () {
      this.$el.find('*[tabindex]').prop('tabindex', 0);
      this.keyboardBehavior.setFocusInView();
    },

    onDomRefresh: function () {
      this.keyboardBehavior.refreshFocusEngage();
    },

    currentlyFocusedElement: function (shiftTab) {
      return this.keyboardBehavior.getCurrentlyFocusedElement(shiftTab);
    },

    onLastTabElement: function (shiftTab, event) {
      return this.keyboardBehavior.isOnLastTabElement(shiftTab, event);
    },

    getValue: function () {
      var selected = _.filter(document.querySelectorAll('input[name="versioncontrol"]'),
          function (element) {
            return element.checked;
          });
      return selected[0].value === lang.currentFolder ? 0 : 2;
    }
  });
  return DisableVersioningView;

});


