      const otcCheckMarkIcon = $('<otc-icon></otc-icon>').attr({
      type: 'raw',
      size: '16',
      svg: jatoActionIcons.actionCheckmark
    });
      var prevPermissionSelected = this.$el.find('.csui-folder-permissions-item.selected');
