csui.define('csui/utils/testutils/async.test.utils',['module', 'csui/lib/underscore', 'csui/lib/jquery', 'csui/models/view.state.model'], function(module, _, $, viewStateModel) {

  var pendingTimers = [];
  // todo: 1) asyncElement could keep running even after the test times out. Some tests
  // todo:    call this function multiple times. This means the test could very well time out
  // todo:    before the second or the third asyncElement call finishes.
  // todo: 2) Simplify it. This function tries to monitor adding and removing.
  // todo: 3) Reduce the timeout to a fraction of the unit test timeout.
  // todo: Very dangerous function. Tests could fail because some other test is still running
  // todo: after it timed out. For now any suite calls asyncElement must call cancelAllAsync
  // todo: in the afterAll in the top most subscribe.
  function asyncElement(parent, selector, options) {
    var deferred      = $.Deferred(),
        timeout       = window.jasmine ? window.jasmine.DEFAULT_TIMEOUT_INTERVAL : 10000,
        newOptions    = {},
        intervalSoFar = 0,               
        el, intervalRef;
        timeout -= timeout/10;
    if (typeof options === 'number') {
      newOptions.interval = options;
    } else if (typeof options === 'boolean') {
      newOptions.removal = options;
    } else {
      newOptions = options;
    }
    options = _.extend({interval: 50, removal: false, length: 0}, newOptions);
    if (!parent || !selector) {
      console.warn('parent or child selector missing');
      deferred.reject();
    } else {
      el = $(parent).find(selector);
      //options.removal and length checking due to the use case
      //when element adding and removing is chained
      if (options.removal ? el.length === options.length : el.length > options.length) {
        deferred.resolve(el);
      } else {
        // to help better find test cases, where the timeout errors occur
        // create error object here, to have sync stack in error trace.
        var timeoutError = new Error('Waiting for element "' + selector + '" timed out.');
        intervalRef = setInterval(function () {
          intervalSoFar += options.interval;
          el = $(parent).find(selector);
          if ((options.removal ? el.length === options.length : el.length > options.length)) {
            stopTimer(intervalRef);
            deferred.resolve(el);
          } else if (intervalSoFar >= timeout) {
            stopTimer(intervalRef);
            throw timeoutError;
          }
        }, options.interval);
        pendingTimers.push(intervalRef);
      }
    }
    //no need of deferred.reject if element not found as karma will timeout
    return deferred.promise();
  }

  function stopTimer(intervalRef) {
    clearInterval(intervalRef);
    pendingTimers = _.without(pendingTimers, intervalRef);
  }

  return {
    asyncElement: asyncElement,
    cancelAllAsync: function() {
      if (pendingTimers.length > 0) {
        console.error("Total "+pendingTimers.length+" was running. Tests needs to be fixed.");
      }
      pendingTimers.forEach(function (intervalRef) {
        clearInterval(intervalRef);
      });
      pendingTimers = [];
    },
    restoreEnvironment:function() {
      // todo: remove any css or attributes on the body.
      // todo: monitor the views creation and make sure all destroyed.
      $('body').empty();
      viewStateModel.clean();
    },

    waitFor: function(check,message,timeout){
      timeout===undefined && (timeout = 1000);
      var deferred = $.Deferred();
      if (check()) {
        deferred.resolve();
      } else {
        var state = {
          clear: function () {
            if (this.timeout) {
              clearTimeout(this.timeout);
              delete this.timeout;
            }
            if (this.interval) {
              clearInterval(this.interval);
              delete this.interval;
            }
          },
          interval: setInterval(function () {
            if (check()) {
              state.clear();
              deferred.resolve();
            }
          }, 100),
          timeout: setTimeout(function () {
            state.clear();
            deferred.reject(state.error);
          }, timeout),
          error: new Error(_.str.sformat("Timeout {0} reached while waiting for {1}.",timeout,message))
        };
      }
      return deferred.promise();
    },

    /**
     * check if an element is hidden or clipped by any of its ancestors and return that ancestor.
     * this can be used to check if an element is really visible or hidden.
     * 
     * for simplicity the function checks only the center point of the element and
     * does not care of any other overlapping situation.
     * 
     * returns the hiding ancestor element, if the element is hidden or clipped.
     * returns null, if element is null or undefined.
     * returns the element, if element is not visible at all.
     * returns undefined, if the element is neither hidden nor clipped by any of its ancestors.
     */
    findHidingElement: function(element, root) {

      if (!element) {
        return null;
      }
      var elementStyle = window.getComputedStyle(element);
      var elementRect = element.getBoundingClientRect();
      var middleX = elementRect.x + elementRect.width / 2;
      var middleY = elementRect.y + elementRect.height / 2;
      //console.log(element,elementStyle["display"],middleX,middleY,elementRect);
      if (elementStyle["display"] === "none") {
        return element;
      }
      if (elementRect.width === 0 || elementRect.height === 0) {
        return element;
      }

      root = root ? root : document.body;
      var parentElement = element.parentElement;
      while (parentElement) {

        var parentStyle = window.getComputedStyle(parentElement);
        var parentRect = parentElement.getBoundingClientRect();
        var overflowX = parentStyle["overflow-x"] !== "clip" && parentStyle["overflow-x"] !== "hidden";
        var overflowY = parentStyle["overflow-y"] !== "clip" && parentStyle["overflow-y"] !== "hidden";
        var visibleX = overflowX || parentRect.width && parentRect.left <= middleX && middleX <= parentRect.right;
        var visibleY = overflowY || parentRect.height && parentRect.top <= middleY && middleY <= parentRect.bottom;
        //console.log(parentElement,parentStyle["display"],parentStyle["overflow-x"],parentStyle["overflow-y"],visibleX,visibleY,parentRect);
        if (parentStyle["display"] === "none") {
          return parentElement;
        }
        if (!visibleX || !visibleY) {
          return parentElement;
        }
        if (parentElement === root) {
          return undefined;
        }
        parentElement = parentElement.parentElement;
      }
      return undefined;
    },

    isElementVisible: function(element, root) {
      var visible = this.findHidingElement(element, root) === undefined;
      return visible;
    }
  };
});




