csui.define('csui/models/permission/dynamic.permission/dynamic.permission.mixin',["csui/utils/url"], function (Url) {
  "use strict";

  let ServerAdaptorMixin = {
    mixin: function (prototype) {
      return Object.assign(prototype, {
        makeServerAdaptor: function () {
          return this;
        },
        url: function () {
          let nodeId = this.nodeId;
          let roleId = this.get("role_id");
          let url = this.options.connector.getConnectionUrl().getApiBase("v2");
          url = Url.combine(url, "nodes", nodeId, "permissions", "dynamic");
          const addingNewRole = this.isNew && this.isNew();
          if (!addingNewRole) {
            url = Url.combine(url, roleId);
          }
          return url;
        },

        parse: function (response) {
          return response;
        },
      });
    },
  };

  return ServerAdaptorMixin;
});


csui.define('csui/models/permission/dynamic.permission/dynamic.permission.model',[
  'nuc/lib/backbone',
  'nuc/models/mixins/connectable/connectable.mixin',
  'nuc/models/mixins/uploadable/uploadable.mixin',
  'csui/models/permission/dynamic.permission/dynamic.permission.mixin'
], function (Backbone, ConnectableMixin, UploadableMixin, ServerAdaptorMixin) {
  'use strict';

  const PERMISSIONS = {
    READ: {
      level: 1,
      permissions: ["see", "see_contents"]
    },
    WRITE: {
      level: 2,
      permissions: ["add_items", "delete", "delete_versions", "edit_attributes", "modify", "reserve", "see", "see_contents"]
    },
    FULL_CONTROL: {
      level: 3,
      permissions: ["add_items", "delete", "delete_versions", "edit_attributes", "edit_permissions", "modify", "reserve", "add_major_version", "see", "see_contents"]
    }
  };
  let DynamicPermissionModel = Backbone.Model.extend({

    constructor: function DynamicPermissionModel(attributes = {}, options = {}) {
      Backbone.Model.prototype.constructor.call(this, attributes, options);
      this.options = {};
      this.options.connector = options.connector;
      this.PERMISSION_LEVEL_READ = this._getPermissionLevel("READ");
      this.PERMISSION_LEVEL_WRITE = this._getPermissionLevel("WRITE");
      this.PERMISSION_LEVEL_FULL_CONTROL = this._getPermissionLevel("FULL_CONTROL");
      this.makeConnectable(options)
        .makeUploadable(options);
    },

    getPermissionLevel: function (permissions) {
      let value;
      permissions = this.get('permissions') || this.get('dynamicpermissions');
      if (permissions.includes("edit_permissions")) {
        value = this.PERMISSION_LEVEL_FULL_CONTROL;
      } else if (permissions.includes("delete")) {
        value = this.PERMISSION_LEVEL_WRITE;
      } else if (permissions.includes("see_contents") &&
        permissions.length === 2) {
        value = this.PERMISSION_LEVEL_READ;
      }
      return value;
    },

    getPermissionsByLevel: function (level) {
      for (const key in PERMISSIONS) {
        if (PERMISSIONS[key].level === level) {
          return PERMISSIONS[key].permissions;
        }
      }
    },

    _getPermissionLevel: function (permissionType) {
      return PERMISSIONS[permissionType].level;
    }
  });

  ConnectableMixin.mixin(DynamicPermissionModel.prototype);
  UploadableMixin.mixin(DynamicPermissionModel.prototype);
  ServerAdaptorMixin.mixin(DynamicPermissionModel.prototype);

  return DynamicPermissionModel;
});

csui.define('csui/models/permission/dynamic.permission/dynamic.permission.collection.mixin',[
  'nuc/utils/url'
], function (Url) {
  'use strict';
  let ServerAdaptorMixin = {
    mixin: function (prototype) {
      return Object.assign(prototype, {
        makeServerAdaptor: function () {
          return this;
        },
        url: function () {
          let query;
          let url = Url.combine(this.connector.getConnectionUrl().getApiBase('v2'), 'nodes', this.options.node.get('id'));
          query = Url.combineQueryString(
            {
              fields: ['dynamicpermissions'],
              expand: ['dynamicpermissions{role_id}']
            }, query);
          if (query) {
            url += '?' + query;
          }
          return url;
        },
        parse: function (response) {
          if (response.results?.data?.dynamicpermissions) {
            let dynamicPermissionCollection = [];
            if (Array.isArray(response.results.data.dynamicpermissions)) {
              for (let data of response.results.data.dynamicpermissions) {
                let mergedObject = Object.assign(data, data.role_id_expand); //combining role_id_expand object with parent object for rendering table columns based on rest response
                delete mergedObject.role_id_expand; //deleting role_id_expand as the contents are already merged with parent object
                mergedObject.dynamicpermissions = mergedObject.permissions;
                dynamicPermissionCollection.push(mergedObject);
              }
            }
            return dynamicPermissionCollection;
          }
        }
      });
    }
  };
  return ServerAdaptorMixin;
});

